import{_ as n,o as r,c as t,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const o=JSON.parse('{"title":"Allgemeine Daten gruppenweise bearbeiten","description":"","frontmatter":{},"headers":[],"relativePath":"schild3/gruppenprozesse.md","filePath":"schild3/gruppenprozesse.md"}'),s={name:"schild3/gruppenprozesse.md"};function d(h,e,i,u,l,g){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="allgemeine-daten-gruppenweise-bearbeiten" tabindex="-1">Allgemeine Daten gruppenweise bearbeiten <a class="header-anchor" href="#allgemeine-daten-gruppenweise-bearbeiten" aria-label="Permalink to &quot;Allgemeine Daten gruppenweise bearbeiten&quot;">​</a></h1><p>Gruppenprozesse bearbeiten die aktuell ausgewählten Schülerinnen und Schüler gemeinsam. Die <a href="/einstieg/grundlagen/einfuehrung-in-die-gruppenprozesse-einfuehrung-in-schild-nrw.html">Einführung</a> zeigt das Prinzip; <a href="/schild3/suchen-gruppenprozesse.html">Auswahl und Suche</a> hilft beim Zusammenstellen der Gruppe.</p><p>Kontrollieren Sie vor jedem Start <strong>gefilterte Menge</strong>, <strong>Markierungen beziehungsweise Bearbeitungsauswahl</strong>, <strong>Zielabschnitt</strong> und <strong>Änderungsmodus</strong>. Das Zurücksetzen auf die Standardauswahl macht gespeicherte Änderungen nicht rückgängig.</p><h2 id="personen-und-laufbahndaten-andern" tabindex="-1">Personen- und Laufbahndaten ändern <a class="header-anchor" href="#personen-und-laufbahndaten-andern" aria-label="Permalink to &quot;Personen- und Laufbahndaten ändern&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Individual- und Lernabschnittsdaten gemeinsam ändern</td><td><a href="/schild3/suchen-gruppenprozesse/individualdaten-aendern-gruppenprozesse-allgemein.html">Individualdaten ändern</a></td></tr><tr><td>Rufname und vollständige Vornamen abgleichen</td><td><a href="/schild3/suchen-gruppenprozesse/alle-vornamen-anpassen-gruppenprozesse-allgemein.html">Vornamen anpassen</a></td></tr><tr><td>Gemeinsame Wiedervorlagen mit Termin anlegen</td><td><a href="/schild3/suchen-gruppenprozesse/eintrag-in-die-wiedervorlage-machen-gruppenprozesse-allgemein.html">Wiedervorlagen anlegen</a></td></tr><tr><td>Migrationsmerkmal aus vorhandenen Daten ableiten</td><td><a href="/administration/datenbanken/migrationshintergrund-automatisch-setzen-gruppenprozesse-allgemein.html">Migrationshintergrund setzen</a></td></tr><tr><td>Schulbesuchsjahre neu berechnen</td><td><a href="/schild3/suchen-gruppenprozesse/schulbesuchsjahre-neu-berechnen-gruppenprozesse-allgemein.html">Schulbesuchsjahre berechnen</a></td></tr><tr><td>Ausweisnummern automatisch vergeben</td><td><a href="/schild3/suchen-gruppenprozesse/ausweisnummern-automatisch-generieren-gruppenprozesse-allgemein.html">Ausweisnummern vergeben</a></td></tr></tbody></table><h2 id="zuordnungen-und-schulbesuch-erganzen" tabindex="-1">Zuordnungen und Schulbesuch ergänzen <a class="header-anchor" href="#zuordnungen-und-schulbesuch-erganzen" aria-label="Permalink to &quot;Zuordnungen und Schulbesuch ergänzen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Sprache und Belegungszeitraum zuweisen</td><td><a href="/schild3/suchen-gruppenprozesse/sprachenfolge-zuweisen-gruppenprozesse-allgemein.html">Sprachenfolge zuweisen</a></td></tr><tr><td>Sprachenfolge aus Leistungsdaten ergänzen</td><td><a href="/schild3/suchen-gruppenprozesse/sprachenfolge-aus-leistungsdaten-ermitteln-gruppenprozesse-allgemein.html">Sprachenfolge ermitteln</a></td></tr><tr><td>Denselben Betrieb mehreren Personen zuordnen</td><td><a href="/schild3/suchen-gruppenprozesse/betrieb-adresse-zuweisen-gruppenprozesse-allgemein.html">Betrieb oder Adresse zuweisen</a></td></tr><tr><td>Eigene Schule in der Schulbesuchsliste ergänzen</td><td><a href="/schild3/suchen-gruppenprozesse/eigene-schule-in-abgangsliste-setzen-gruppenprozesse-allgemein.html">Eigene Schule im Schulbesuch</a></td></tr><tr><td>KAoA-Maßnahmen für eine Gruppe erfassen</td><td><a href="/schild3/suchen-gruppenprozesse/kaoa-daten-eingeben-gruppenprozesse-allgemein.html">KAoA-Daten eingeben</a></td></tr></tbody></table><h2 id="vorhandene-angaben-entfernen" tabindex="-1">Vorhandene Angaben entfernen <a class="header-anchor" href="#vorhandene-angaben-entfernen" aria-label="Permalink to &quot;Vorhandene Angaben entfernen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Gespeicherte Schülerfotos entfernen</td><td><a href="/schild3/suchen-gruppenprozesse/fotos-loeschen-gruppenprozesse-allgemein.html">Schülerfotos löschen</a></td></tr><tr><td>Bestimmte Vermerke oder Merkmale entfernen</td><td><a href="/schild3/suchen-gruppenprozesse/vermerke-merkmale-loeschen-gruppenprozesse-allgemein.html">Vermerke und Merkmale löschen</a></td></tr><tr><td>Nicht mehr benötigte Grundschuldaten entfernen</td><td><a href="/schild3/suchen-gruppenprozesse/grundschuldaten-loeschen-gruppenprozesse-allgemein.html">Grundschuldaten löschen</a></td></tr></tbody></table><p>Prüfen Sie vor diesen Löschaktionen die ausgewählte Gruppe und die Hinweise zur Sicherung im jeweiligen Artikel. Das endgültige Entfernen ganzer Datensätze ist unter <a href="/administration/datenschutz.html">Datenschutz und Löschen</a> beschrieben.</p><p>Für Unterricht verwenden Sie <a href="/schild3/faecher-kurse.html">Fächer und Kurse zuweisen</a>. Noten, Prüfungen und Abschnittswechsel sind unter <a href="/zeugnisse/">Zeugnisse und Abschlüsse</a> eingeordnet.</p>',11)])])}const c=n(s,[["render",d]]);export{o as __pageData,c as default};
